<?php
namespace App\Http\Controllers;use App\Models\TransportAlert;use App\Traits\AuthorizesCompanyOwnership;use Illuminate\Http\Request;
class TransportAlertController extends Controller {use AuthorizesCompanyOwnership;public function index(Request$r){return view('transport.alerts.index',['alerts'=>TransportAlert::forCompany($r->user()->company_id)->latest('last_detected_at')->paginate(40)]);}public function acknowledge(Request$r,TransportAlert$a){$this->own($a);$a->update(['status'=>'acknowledged','acknowledged_at'=>now(),'acknowledged_by'=>$r->user()->id]);return back()->with('success','Alerta reconocida.');}public function dismiss(Request$r,TransportAlert$a){$this->own($a);$a->update(['status'=>'dismissed','dismissed_at'=>now(),'dismissed_by'=>$r->user()->id]);return back()->with('success','Alerta descartada.');}}
